const contenedores = $('Obtener Contenedores').all().map(i => i.json);
const paises = $('Obtener Paises').all().map(i => i.json);

const paisMap = new Map(paises.map(p => [p.id_pais, { nombre: p.nombre, iso: p.codigo_iso_alfa2 }]));
const conteos = new Map();

for (const c of contenedores) {
  const idPais = c.id_pais_procedencia;
  if (!idPais) continue;
  conteos.set(idPais, (conteos.get(idPais) || 0) + 1);
}

const lista = [];
for (const [idPais, total] of conteos.entries()) {
  const info = paisMap.get(idPais) || { nombre: 'Desconocido', iso: 'XX' };
  lista.push({ pais_procedencia: info.nombre, codigo_iso_alfa2: info.iso, total_contenedores: total });
}

lista.sort((a, b) => b.total_contenedores - a.total_contenedores || a.pais_procedencia.localeCompare(b.pais_procedencia));

let currentRank = 0;
let prevTotal = null;
const ranked = [];
for (const item of lista) {
  if (item.total_contenedores !== prevTotal) {
    currentRank++;
    prevTotal = item.total_contenedores;
  }
  if (currentRank === 1) {
    ranked.push({ ranking_posicion: 1, ...item });
  }
}

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_pais_con_mas_contenedores',
    criterio: 'Pais de procedencia (contenedor.id_pais_procedencia)',
    total_registros: ranked.length,
    es_parcial: false,
    datos: ranked
  }
}];
